#include <bits/stdc++.h>
using namespace std;

struct Edge {
    int u, v;
    long long w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int E, R;
    cin >> E >> R;

    vector<Edge> edges(R);
    vector<vector<pair<int, int>>> graph(E);

    for (int i = 0; i < R; ++i) {
        int a, b;
        long long c;
        cin >> a >> b >> c;
        --a;
        --b;
        edges[i] = {a, b, c};
        graph[a].push_back({b, i});
        graph[b].push_back({a, i});
    }

    vector<int> tin(E, -1), low(E), isBridge(R, false);
    int timer = 0;

    function<void(int, int)> dfs = [&](int u, int parentEdge) {
        tin[u] = low[u] = timer++;
        for (auto [v, id] : graph[u]) {
            if (id == parentEdge) continue;
            if (tin[v] != -1) {
                low[u] = min(low[u], tin[v]);
            } else {
                dfs(v, id);
                low[u] = min(low[u], low[v]);
                if (low[v] > tin[u]) isBridge[id] = true;
            }
        }
    };

    for (int i = 0; i < E; ++i) {
        if (tin[i] == -1) dfs(i, -1);
    }

    vector<vector<int>> cycles;
    vector<long long> cycleLength;
    vector<bool> seenVertex(E, false), seenEdge(R, false);

    for (int start = 0; start < E; ++start) {
        bool hasCycleEdge = false;
        for (auto [v, id] : graph[start]) {
            if (!isBridge[id]) {
                hasCycleEdge = true;
                break;
            }
        }
        if (!hasCycleEdge || seenVertex[start]) continue;

        vector<int> vertices;
        long long length = 0;
        queue<int> q;
        q.push(start);
        seenVertex[start] = true;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            vertices.push_back(u);

            for (auto [v, id] : graph[u]) {
                if (isBridge[id]) continue;
                if (!seenEdge[id]) {
                    seenEdge[id] = true;
                    length += edges[id].w;
                }
                if (!seenVertex[v]) {
                    seenVertex[v] = true;
                    q.push(v);
                }
            }
        }

        cycles.push_back(move(vertices));
        cycleLength.push_back(length);
    }

    int K;
    cin >> K;

    const long long INF = (1LL << 60);

    while (K--) {
        int x;
        long long T;
        cin >> x >> T;
        --x;

        vector<long long> dist(E, INF);
        priority_queue<pair<long long, int>,
                       vector<pair<long long, int>>,
                       greater<pair<long long, int>>> pq;

        dist[x] = 0;
        pq.push({0, x});

        while (!pq.empty()) {
            auto [d, u] = pq.top();
            pq.pop();
            if (d != dist[u]) continue;

            for (auto [v, id] : graph[u]) {
                long long nd = d + edges[id].w;
                if (nd < dist[v]) {
                    dist[v] = nd;
                    pq.push({nd, v});
                }
            }
        }

        long long answer = INF;
        for (int i = 0; i < (int)cycles.size(); ++i) {
            if (cycleLength[i] < T) continue;
            long long d = INF;
            for (int v : cycles[i]) d = min(d, dist[v]);
            if (d != INF) answer = min(answer, cycleLength[i] + 2 * d);
        }

        cout << (answer == INF ? -1 : answer) << '\n';
    }

    return 0;
}
